// KanjiVG names each SVG by its Unicode code point (e.g. 大 → 05927.svg).
// This lets every downloaded N5 Kanji use the same animation without a
// fragile hand-maintained list of character-to-file mappings.
const kanjiVgCode = char => Array.from(char || '').length === 1 ? char.codePointAt(0).toString(16).padStart(5,'0') : null;

function GrammarGuide({go}){return <section className="grammar-guide"><h2>Ký hiệu viết tắt trong cấu trúc ngữ pháp</h2><div className="grammar-legend"><span><b className="grammar-chip noun">N</b>Danh từ (名詞)</span><span><b className="grammar-chip verb">V</b>Động từ (動詞)</span><span><b className="grammar-chip adj">A</b>Tính từ (形容詞)</span><span><b className="grammar-chip iadj">Aい</b>Tính từ đuôi い</span><span><b className="grammar-chip naadj">Aな</b>Tính từ đuôi な</span><span><b className="grammar-chip sentence">S</b>Câu (文)</span><span><b className="grammar-chip plain">TTT</b>Thể thông thường</span><span><b className="grammar-chip number">Số</b>Số lượng</span><span><b className="grammar-chip place">Địa điểm</b>Nơi chốn</span><span><b className="grammar-chip time">Thời gian</b>Thời điểm</span></div><button className="conjugation-guide" onClick={()=>go('/grammar/conjugation')}><span><b>Bảng chia thể động từ · tính từ</b><small>Thể thông thường, thể て, thể ない, khả năng, bị động, sai khiến.</small></span><em>Xem thêm ›</em></button></section>}
function ConjugationPage({go}){const plainRows=[['Vます','食べる','食べない'],['Vました','食べた','食べなかった'],['Aいです','高い','高くない'],['Aかったです','高かった','高くなかった'],['Aな / Nです','元気だ','元気じゃない'],['Aな / Nでした','元気だった','元気じゃなかった']];const verbRows=[['Vます','ます形','書きます','食べます','します・来(き)ます'],['Vる','từ điển','書く','食べる','する・来る'],['Vて','て形','書いて','食べて','して・来て'],['Vない','ない形','書かない','食べない','しない・来ない'],['Vた','た形','書いた','食べた','した・来た'],['Vれる','khả năng','書ける','食べられる','できる・来られる']];return <section className="simple-page conjugation-page"><button className="grammar-back" onClick={()=>go('/grammar/n5')}>← Ngữ pháp</button><p className="eyebrow">NGỮ PHÁP · CÔNG CỤ HỌC</p><h1>Bảng chia thể động từ · tính từ</h1><p className="intro">Tổng hợp cách chia các thể thường gặp trong tiếng Nhật.</p><section className="conjugation-panel"><h2>Thể thông thường（普通形）</h2><p>Dùng trong hội thoại thân mật, mệnh đề phụ và trước と 思う・と言う・んです…</p><div className="conjugation-table plain-table"><div className="conjugation-row heading"><b></b><b>Khẳng định</b><b>Phủ định</b></div>{plainRows.map(row=><div className="conjugation-row" key={row[0]}>{row.map((item,index)=><span key={item} className={index===0?'dictionary':''}>{item}</span>)}</div>)}</div></section><section className="conjugation-panel"><h2>Tổng hợp các thể động từ</h2><p>Ví dụ: 書く (nhóm 1) · 食べる (nhóm 2) · する・来る (nhóm 3)</p><div className="conjugation-table verb-table"><div className="conjugation-row heading"><b>Thể</b><b></b><b>Nhóm 1</b><b>Nhóm 2</b><b>Nhóm 3</b></div>{verbRows.map(row=><div className="conjugation-row" key={row[0]}>{row.map((item,index)=><span key={`${item}-${index}`} className={index===0?'dictionary':''}>{item}</span>)}</div>)}</div></section></section>}

function StrokeOrder({char,interactive=false}) {
  const host = useRef(null), timer = useRef(), playing = useRef(false), [svg,setSvg] = useState(''),[svgStatus,setSvgStatus]=useState('loading'),[svgRetry,setSvgRetry]=useState(0), code = kanjiVgCode(char);
  useEffect(()=>{const controller=new AbortController();setSvg('');setSvgStatus('loading');if(!code)return;fetch(`/kanjivg/${code}.svg`,{signal:controller.signal}).then(r=>{if(r.status===404){setSvgStatus('empty');return null}if(!r.ok)throw new Error('SVG unavailable');return r.text()}).then(markup=>{if(!controller.signal.aborted&&markup){if(!/<svg[\s>]/i.test(markup)){setSvgStatus('empty');return}setSvg(markup.replace(/^<\?xml[\s\S]*?\?>/,'').replace(/<!--[\s\S]*?-->/g,'').replace(/<!DOCTYPE[\s\S]*?\]>\s*/,''));setSvgStatus('ready')}}).catch(()=>{if(!controller.signal.aborted)setSvgStatus('error')});return()=>{controller.abort();clearTimeout(timer.current);playing.current=false}},[code,svgRetry]);
  const resetPaths=()=>host.current?.querySelectorAll('path').forEach(path=>{path.style.transition='none';path.style.strokeDasharray='none';path.style.strokeDashoffset='0'});
  useEffect(()=>{resetPaths()},[svg]);
  const play=()=>{if(svgStatus==='error'){setSvgRetry(value=>value+1);return}if(!interactive||!svg||!host.current||playing.current)return;clearTimeout(timer.current);const paths=[...host.current.querySelectorAll('path')];if(!paths.length)return;playing.current=true;paths.forEach(path=>{const length=Math.max(1,Math.ceil(path.getTotalLength()));path.style.transition='none';path.style.strokeDasharray=String(length);path.style.strokeDashoffset=String(length);path.getBoundingClientRect()});requestAnimationFrame(()=>requestAnimationFrame(()=>paths.forEach((path,index)=>setTimeout(()=>{path.style.transition='stroke-dashoffset 420ms ease-out';path.style.strokeDashoffset='0'},index*470))));timer.current=setTimeout(()=>{resetPaths();playing.current=false},paths.length*470+520)};
  if(!code) return <div className="kanjivg-board fallback"><b>{char}</b><small>SVG nét viết đang được bổ sung</small></div>;
  const board=<div className="kanjivg-board" ref={host} aria-label={`Thứ tự nét chữ ${char}`}>{svg?<div dangerouslySetInnerHTML={{__html:svg}}/>:<span>{svgStatus==='empty'?'Chưa có SVG nét viết.':svgStatus==='error'?'Không tải được nét viết.':'Đang tải nét viết…'}</span>}</div>;
  return interactive?<button type="button" className="stroke-order-play" onClick={play} aria-label={`Xem hoạt ảnh thứ tự nét chữ ${char}`}>{board}<em>{svgStatus==='error'?'Nhấn để thử lại':svgStatus==='ready'?'Nhấn để xem nét viết':''}</em></button>:board;
}

const speakJapanese=(text,rate=.82)=>{
  if(!text||!window.speechSynthesis||!window.SpeechSynthesisUtterance)return false;
  window.speechSynthesis.cancel();
  const utterance=new SpeechSynthesisUtterance(text);
  utterance.lang='ja-JP';utterance.rate=rate;
  const japaneseVoice=window.speechSynthesis.getVoices().find(voice=>voice.lang?.toLowerCase().startsWith('ja'));
  if(japaneseVoice)utterance.voice=japaneseVoice;
  window.speechSynthesis.speak(utterance);
  return true;
};

const DRAW_SIZE = 400;
const STROKE_OPTIONS = { size: 16, thinning: 0.5, smoothing: 0.5, streamline: 0.5, simulatePressure: true, last: true, start: { cap: true }, end: { cap: true } };
const svgPath = points => {
  const outline = getStroke(points.map(point => [point.x, point.y, point.pressure]), STROKE_OPTIONS);
  if (!outline.length) return '';
  return `${outline.reduce((path, [x,y], index) => {
    const [nextX,nextY] = outline[(index + 1) % outline.length];
    return `${path}${index ? 'L' : 'M'}${x},${y} ${(x + nextX) / 2},${(y + nextY) / 2}`;
  }, '')}Z`;
};
const rasterizeForDaKanji = (strokes, width=DRAW_SIZE, height=DRAW_SIZE) => {
  const source=document.createElement('canvas');source.width=width;source.height=height;
  const ctx=source.getContext('2d',{willReadFrequently:true});ctx.fillStyle='#000';ctx.fillRect(0,0,width,height);ctx.strokeStyle='#fff';ctx.lineWidth=16;ctx.lineCap='round';ctx.lineJoin='round';
  let minX=width,minY=height,maxX=0,maxY=0;
  strokes.forEach(stroke=>{if(!stroke.length)return;ctx.beginPath();ctx.moveTo(stroke[0].x,stroke[0].y);stroke.forEach((point,index)=>{if(index)ctx.lineTo(point.x,point.y);minX=Math.min(minX,point.x);minY=Math.min(minY,point.y);maxX=Math.max(maxX,point.x);maxY=Math.max(maxY,point.y)});if(stroke.length===1)ctx.lineTo(stroke[0].x,stroke[0].y);ctx.stroke()});
  minX=Math.max(0,Math.floor(minX-16));minY=Math.max(0,Math.floor(minY-16));maxX=Math.min(width,Math.ceil(maxX+16));maxY=Math.min(height,Math.ceil(maxY+16));
  const glyphWidth=Math.max(1,maxX-minX),glyphHeight=Math.max(1,maxY-minY),padding=Math.ceil(Math.max(glyphWidth,glyphHeight)*.1),side=Math.max(glyphWidth,glyphHeight)+padding*2;
  let left=Math.floor(minX-(side-glyphWidth)/2),top=Math.floor(minY-(side-glyphHeight)/2);left=Math.max(0,left);top=Math.max(0,top);if(left+side>width)left=Math.max(0,width-side);if(top+side>height)top=Math.max(0,height-side);
  const crop=document.createElement('canvas');crop.width=Math.min(side,width-left);crop.height=Math.min(side,height-top);crop.getContext('2d').drawImage(source,left,top,crop.width,crop.height,0,0,crop.width,crop.height);return crop.toDataURL('image/png');
};
// The Chinese model was trained on CASIA-style images: dark ink on white
// paper. Keep this separate from DaKanji's white-ink-on-black contract.
const rasterizeForHanzi = (strokes, width=DRAW_SIZE, height=DRAW_SIZE) => {
  const source=document.createElement('canvas');source.width=width;source.height=height;
  const ctx=source.getContext('2d',{willReadFrequently:true});ctx.fillStyle='#fff';ctx.fillRect(0,0,width,height);ctx.strokeStyle='#000';ctx.lineWidth=16;ctx.lineCap='round';ctx.lineJoin='round';
  let minX=width,minY=height,maxX=0,maxY=0;
  strokes.forEach(stroke=>{if(!stroke.length)return;ctx.beginPath();ctx.moveTo(stroke[0].x,stroke[0].y);stroke.forEach((point,index)=>{if(index)ctx.lineTo(point.x,point.y);minX=Math.min(minX,point.x);minY=Math.min(minY,point.y);maxX=Math.max(maxX,point.x);maxY=Math.max(maxY,point.y)});if(stroke.length===1)ctx.lineTo(stroke[0].x,stroke[0].y);ctx.stroke()});
  minX=Math.max(0,Math.floor(minX-16));minY=Math.max(0,Math.floor(minY-16));maxX=Math.min(width,Math.ceil(maxX+16));maxY=Math.min(height,Math.ceil(maxY+16));
  const glyphWidth=Math.max(1,maxX-minX),glyphHeight=Math.max(1,maxY-minY),padding=Math.ceil(Math.max(glyphWidth,glyphHeight)*.1),side=Math.max(glyphWidth,glyphHeight)+padding*2;
  let left=Math.floor(minX-(side-glyphWidth)/2),top=Math.floor(minY-(side-glyphHeight)/2);left=Math.max(0,left);top=Math.max(0,top);if(left+side>width)left=Math.max(0,width-side);if(top+side>height)top=Math.max(0,height-side);
  const crop=document.createElement('canvas');crop.width=Math.min(side,width-left);crop.height=Math.min(side,height-top);crop.getContext('2d').drawImage(source,left,top,crop.width,crop.height,0,0,crop.width,crop.height);return crop.toDataURL('image/png');
};

function WritingCanvas({onRecognize,language='ja'}) {
  const svgRef=useRef(null), drawing=useRef(false), active=useRef([]), strokesRef=useRef([]), timer=useRef();
  const [strokes,setStrokes]=useState([]),[preview,setPreview]=useState([]);
  const commit=next=>{strokesRef.current=next;setStrokes(next)};
  const position=e=>{const r=svgRef.current.getBoundingClientRect();return {x:(e.clientX-r.left)*DRAW_SIZE/r.width,y:(e.clientY-r.top)*DRAW_SIZE/r.height,pressure:e.pointerType==='pen'&&e.pressure>0?e.pressure:.5}};
  const begin=e=>{e.preventDefault();clearTimeout(timer.current);drawing.current=true;svgRef.current.setPointerCapture?.(e.pointerId);active.current=[position(e)];setPreview([...active.current])};
  const draw=e=>{if(!drawing.current)return;e.preventDefault();for(const event of e.getCoalescedEvents?.()||[e]) active.current.push(position(event));setPreview([...active.current])};
  const recognize=next=>onRecognize({strokes:next.map(stroke=>stroke.map(({x,y,pressure})=>[x,y,pressure])),image:language==='zh'?rasterizeForHanzi(next):rasterizeForDaKanji(next),canvasSize:DRAW_SIZE,strokeCount:next.length});
  const end=e=>{if(!drawing.current)return;drawing.current=false;svgRef.current.releasePointerCapture?.(e.pointerId);const stroke=active.current;active.current=[];setPreview([]);if(!stroke.length)return;const next=[...strokesRef.current,stroke];commit(next);clearTimeout(timer.current);timer.current=setTimeout(()=>recognize(next),450)};
  const undo=()=>{clearTimeout(timer.current);commit(strokesRef.current.slice(0,-1))};
  const clear=()=>{clearTimeout(timer.current);active.current=[];setPreview([]);commit([])};
  const search=()=>{if(strokesRef.current.length){clearTimeout(timer.current);recognize(strokesRef.current)}};
  const renderStroke=(stroke,index,kind='saved')=>{const path=svgPath(stroke);return path?<path key={`${kind}-${index}`} d={path} className="draw-stroke"/>:null};
  const hasInk=strokes.length>0||preview.length>0;
  return <div className="canvas-wrap"><p className="canvas-title">{language==='zh'?'Viết một Hán tự':'Viết một Kanji'}</p><div className="canvas-stage"><svg ref={svgRef} className="vector-writing-pad" viewBox={`0 0 ${DRAW_SIZE} ${DRAW_SIZE}`} role="img" aria-label={language==='zh'?'Vùng viết Hán tự':'Vùng viết Kanji'} onPointerDown={begin} onPointerMove={draw} onPointerUp={end} onPointerCancel={end}><defs><pattern id="writing-dots" x="14" y="14" width="28" height="28" patternUnits="userSpaceOnUse"><circle cx="0" cy="0" r="1" className="guide-dot"/></pattern></defs><rect width={DRAW_SIZE} height={DRAW_SIZE} fill="url(#writing-dots)"/><line x1="0" y1={DRAW_SIZE/2} x2={DRAW_SIZE} y2={DRAW_SIZE/2} className="guide-line"/><line x1={DRAW_SIZE/2} y1="0" x2={DRAW_SIZE/2} y2={DRAW_SIZE} className="guide-line"/>{strokes.map((stroke,index)=>renderStroke(stroke,index))}{preview.length>0&&renderStroke(preview,'active','active')}</svg></div><div className="canvas-controls"><button onClick={undo} disabled={!strokes.length} aria-label="Hoàn tác nét vừa viết">↶</button><button onClick={clear} disabled={!hasInk} aria-label="Xóa toàn bộ nét vẽ">♲</button><button className="canvas-search" onClick={search} disabled={!strokes.length} aria-label={language==='zh'?'Nhận diện Hán tự':'Nhận diện Kanji'}>⌕</button></div></div>
}

function FlashcardWritingPad({targets,word}){
 const canvasRef=useRef(null),drawing=useRef(false),active=useRef([]),strokes=useRef([]),[hasInk,setHasInk]=useState(false),[targetIndex,setTargetIndex]=useState(0),[state,setState]=useState(''),[recognized,setRecognized]=useState('');
 const target=targets[targetIndex];
 const drawGuide=c=>{const ctx=c.getContext('2d');ctx.clearRect(0,0,c.width,c.height);ctx.save();ctx.strokeStyle='#8fa1bd';ctx.lineWidth=1.5;ctx.setLineDash([5,6]);ctx.beginPath();ctx.moveTo(0,c.height/2);ctx.lineTo(c.width,c.height/2);ctx.stroke();ctx.beginPath();ctx.moveTo(c.width/2,0);ctx.lineTo(c.width/2,c.height);ctx.stroke();ctx.restore()};
 const reset=()=>{strokes.current=[];active.current=[];setHasInk(false);drawGuide(canvasRef.current)};
 useEffect(()=>{setTargetIndex(0);setState('');setRecognized('');requestAnimationFrame(reset)},[targets.join('')]);
 const point=e=>{const r=canvasRef.current.getBoundingClientRect();return{x:(e.clientX-r.left)*canvasRef.current.width/r.width,y:(e.clientY-r.top)*canvasRef.current.height/r.height,pressure:e.pointerType==='pen'&&e.pressure>0?e.pressure:.5}};
 const start=e=>{e.stopPropagation();drawing.current=true;canvasRef.current.setPointerCapture?.(e.pointerId);const p=point(e),ctx=canvasRef.current.getContext('2d');active.current=[p];ctx.setLineDash([]);ctx.strokeStyle='#f1f7ed';ctx.lineWidth=6;ctx.lineCap='round';ctx.lineJoin='round';ctx.beginPath();ctx.moveTo(p.x,p.y)};
 const draw=e=>{if(!drawing.current)return;e.stopPropagation();for(const event of e.getCoalescedEvents?.()||[e]){const p=point(event);active.current.push(p);canvasRef.current.getContext('2d').lineTo(p.x,p.y)}canvasRef.current.getContext('2d').stroke();setHasInk(true)};
 const end=e=>{if(!drawing.current)return;drawing.current=false;canvasRef.current.releasePointerCapture?.(e.pointerId);if(active.current.length)strokes.current.push(active.current);active.current=[]};
 const clear=e=>{e.stopPropagation();setState('');setRecognized('');reset()};
 const check=async e=>{e.stopPropagation();if(!hasInk||!target)return;setState('checking');setRecognized('');try{const image=rasterizeForDaKanji(strokes.current,320,320);const response=await apiFetch('http://localhost:8010/api/recognition',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({image,rasterized:true,stroke_count:strokes.current.length,top_k:3})});const data=await response.json();if(!response.ok)throw new Error(data.detail||'Không thể nhận diện');const detected=data.predictions?.[0]?.kanji||'';setRecognized(detected);if(detected===target){setState('correct');if(targetIndex+1<targets.length){setTargetIndex(i=>i+1);reset()}}else setState('incorrect')}catch{setState('error')}};
 const status=state==='correct'?`✓ ĐÚNG · ${recognized}`:state==='incorrect'?(recognized?`✕ CHƯA ĐÚNG · ${recognized}`:'✕ CHƯA NHẬN DIỆN ĐƯỢC'):state==='checking'?'ĐANG NHẬN DIỆN…':state==='error'?'KHÔNG KẾT NỐI ĐƯỢC AI':'NHẬN DIỆN KANJI';
 return <div className="flash-writing" onClick={e=>e.stopPropagation()}><div className="flash-writing-head"><strong className={`recognition-status ${state}`}>{status}</strong><button onClick={clear} disabled={!hasInk}>↺ Xóa</button></div><canvas ref={canvasRef} width="320" height="320" onPointerDown={start} onPointerMove={draw} onPointerUp={end} onPointerCancel={end}/>{target&&<div className="writing-actions"><button onClick={check} disabled={!hasInk}>Nhận diện</button></div>}</div>
}

